<script setup>
import {computed,ref,reactive,onMounted,onUnmounted,watch,nextTick} from 'vue';
import Pager from '../Pager.vue';
import QzoneSocialSettings from './QzoneSocialSettings.vue';
import {usePage,stamp,errorMessage} from './resources.js';
const props=defineProps(['request','notify','user','viewState','navigate']);
const controller=new AbortController();const api=(path,options={})=>props.request(path,{...options,signal:AbortSignal.any([controller.signal,AbortSignal.timeout(options.timeout||40000)]),body:options.body===undefined?undefined:JSON.stringify(options.body)});
const freshness=reactive({bridge:false,policy:false,whitelist:false,plugins:false});
const ui=usePage({toast:props.notify}), bridge=ref(null), autonomy=ref(null), whitelist=ref(null), chatPlugin=ref(null), warnings=ref([]);
const group=ref(props.viewState.group||''), scene=ref(props.viewState.scene||'handoff');
const scenes=[['handoff','接上最近的事','最近聊了什么，还有什么需要跟进'],['materials','群文件资料','核对群规、活动材料与来源摘录'],['ability','群内能力排查','检查接入范围、开关和最近执行结果']];
const groupName=computed(()=>bridge.value?.groups?.find(g=>g.id===group.value)?.name||'当前群');
const scope=computed(()=>'group:'+group.value);
const groupRule=reactive({history:'',files:'',reactions:''});const scopeDirty=ref(false), changedCapabilities=reactive(new Set());
const effective=computed(()=>({...autonomy.value?.policy,...autonomy.value?.policy?.scopes?.[scope.value]}));
const whiteEntry=computed(()=>whitelist.value?.groups?.find(g=>String(g.id_group)===group.value));
const activity=computed(()=>(autonomy.value?.events||[]).filter(e=>e.scope===scope.value));
const notes=computed(()=>(autonomy.value?.notes||[]).filter(n=>n.scope===scope.value));
const activityPage=ref(0), filePage=ref(0), fileQuery=ref(''), folder=ref(''), folderName=ref(''), files=ref([]), filesBusy=ref(false), fileError=ref(''), docsTruncated=ref(false);
const filteredFiles=computed(()=>files.value.filter(f=>f.name.toLowerCase().includes(fileQuery.value.toLowerCase())));
function pageRows(rows,page){const actual=Math.min(page,Math.max(0,Math.ceil(rows.length/15)-1));return rows.slice(actual*15,actual*15+15);}
const brief=ref(null), briefBusy=ref(false), briefError=ref(''), briefMode=ref('handoff');
const sectionNames={topics:'主要讨论',decisions:'已明确的决定',followups:'待跟进事项',questions:'尚待回答'};
const sourceNames={history:'聊天消息',notices:'群公告',todos:'已有群待办'};
const dialog=ref(null), detailTitle=ref(''), detail=ref(null), detailError=ref(''), detailBusy=ref(false), copyText=ref(''), copyField=ref(null);
let groupRevision=0, detailRevision=0, fileRevision=0;
onUnmounted(()=>{controller.abort();groupRevision++;detailRevision++;fileRevision++;});
function syncRule(){if(scopeDirty.value)return;const rule=autonomy.value?.policy?.scopes?.[scope.value]||{};for(const key of Object.keys(groupRule))groupRule[key]=typeof rule[key]==='boolean'?String(rule[key]):'';}
async function refresh(){if(props.user?.role!=='owner')return;await ui.load(()=>Promise.allSettled([api('qq/bridge'),api('qq/autonomy'),api('chat/whitelist'),api('plugins')]),results=>{
 warnings.value=[];
 const [a,b,c,d]=results;
 freshness.bridge=a.status==='fulfilled';freshness.policy=b.status==='fulfilled';freshness.whitelist=c.status==='fulfilled';freshness.plugins=d.status==='fulfilled';
 if(a.status==='fulfilled'){bridge.value=a.value;if(!bridge.value.groups?.some(g=>g.id===group.value))group.value=bridge.value.groups?.[0]?.id||'';}else warnings.value.push('QQ连接信息暂不可用，未确认当前接入状态。');
 if(b.status==='fulfilled'){autonomy.value=b.value;syncRule();}else warnings.value.push('能力策略和执行记录未读到，暂不修改设置。');
 if(c.status==='fulfilled')whitelist.value=c.value;else warnings.value.push('聊天白名单未读到，不能判断此群是否接入。');
 if(d.status==='fulfilled')chatPlugin.value=d.value.find(p=>p.id==='chat'||p.id.endsWith('.chat'))||null;
 });}
onMounted(refresh);defineExpose({refresh});
watch(group,()=>{groupRevision++;fileRevision++;fileError.value='';files.value=[];filesBusy.value=false;folder.value='';folderName.value='';fileQuery.value='';filePage.value=0;activityPage.value=0;brief.value=null;briefBusy.value=false;briefError.value='';scopeDirty.value=false;changedCapabilities.clear();syncRule();props.viewState.group=group.value;if(scene.value==='materials'&&group.value)loadFiles();});
watch(scene,value=>{props.viewState.scene=value;if(value==='materials'&&group.value&&!files.value.length)loadFiles();});
watch(fileQuery,()=>filePage.value=0);
async function makeBrief(){if(!group.value||briefBusy.value)return;const rev=groupRevision;briefBusy.value=true;briefError.value='';try{const result=await api(`qq/groups/${group.value}/brief`,{method:'POST',body:{mode:briefMode.value}});if(rev===groupRevision)brief.value=result;}catch(e){if(rev===groupRevision)briefError.value=errorMessage(e);}finally{if(rev===groupRevision)briefBusy.value=false;}}
function evidence(ids){return (brief.value?.sources||[]).filter(s=>ids.includes(s.id));}
async function copyBrief(){const b=brief.value;if(!b)return;const lines=[`${groupName.value} · 近期交接草稿（待核对）`,stamp(b.created)];for(const [key,title] of Object.entries(sectionNames)){const items=b.sections[key]||[];if(items.length)lines.push('\n'+title,...items.map(i=>'· '+i.text));}lines.push('\n范围：'+b.coverage);await copy(lines.join('\n'));}
async function copy(text){try{if(!navigator.clipboard)throw new Error();await navigator.clipboard.writeText(text);props.notify('已复制，可自行核对后使用');}catch{detailRevision++;copyText.value=text;detail.value=null;detailTitle.value='复制草稿';detailError.value='';detailBusy.value=false;await nextTick();if(!dialog.value.open)dialog.value.showModal();await nextTick();copyField.value?.select();}}
async function loadFiles(target=folder.value,label=folderName.value){if(!group.value)return;const rev=++fileRevision,gid=group.value;filesBusy.value=true;fileError.value='';try{const d=await api(`qq/groups/${gid}/documents?folder_id=${encodeURIComponent(target)}`);if(rev!==fileRevision||gid!==group.value)return;folder.value=target;folderName.value=label;files.value=d.items||[];docsTruncated.value=!!d.truncated;filePage.value=0;}catch(e){if(rev===fileRevision)fileError.value=errorMessage(e);}finally{if(rev===fileRevision)filesBusy.value=false;}}
async function showDetail(title,path,options){detailTitle.value=title;detail.value=null;copyText.value='';detailError.value='';detailBusy.value=true;const rev=++detailRevision;await nextTick();if(!dialog.value.open)dialog.value.showModal();try{const d=await api(path,options);if(rev===detailRevision)detail.value=d;}catch(e){if(rev===detailRevision)detailError.value=errorMessage(e);}finally{if(rev===detailRevision)detailBusy.value=false;}}
function close(){detailRevision++;dialog.value.close();detail.value=null;copyText.value='';}
async function readFile(file){await showDetail(file.name,`qq/groups/${group.value}/file/read`,{method:'POST',body:{file_id:file.id,folder_id:folder.value}});try{autonomy.value=await api('qq/autonomy');syncRule();}catch{}}
async function saveRule(){if(!autonomy.value||!group.value)return;const gid=group.value,patch={};for(const key of changedCapabilities)patch[key]=groupRule[key]===''?null:groupRule[key]==='true';await ui.run('scope:'+gid,async()=>{autonomy.value=await api(`qq/groups/${gid}/capabilities`,{method:'PUT',body:patch});if(gid===group.value){scopeDirty.value=false;changedCapabilities.clear();syncRule();}},'已保存本群改动，未调整的能力和其他群保持原值');}

const rawKind=ref('storage'),rawResult=ref(null),rawBusy=ref(false);
watch(group,()=>rawResult.value=null);
async function rawRead(){if(!group.value||rawBusy.value)return;const rev=groupRevision;rawBusy.value=true;try{const d=await api(`qq/groups/${group.value}/${rawKind.value}`);if(rev===groupRevision)rawResult.value=d;}catch(e){props.notify(errorMessage(e));}finally{rawBusy.value=false;}}
</script>
<template><div class="qq-workbench">
 <section v-if="user?.role!=='owner'" class="panel"><div class="empty">仅所有者可管理群内能力与资料。</div></section>
 <template v-else>
 <section class="panel"><div class="panel-head"><div><h3>QQ群工作台</h3><p>先选要处理事情的群，再选工作场景。</p></div><button class="button small" :disabled="ui.loading.value" @click="refresh">更新状态</button></div><div class="panel-body qq-group-picker"><label>当前群<select v-model="group" class="input" aria-label="工作群"><option v-for="g in bridge?.groups||[]" :key="g.id" :value="g.id">{{g.name}}（{{g.id}}）</option></select></label><div class="qq-connection"><span class="badge" :class="freshness.bridge&&bridge?.status?.good?'ok':'warn'">{{freshness.bridge&&bridge?.status?.good?'QQ连接正常':'连接待核对'}}</span><small class="mono">{{bridge?.implementation?.app_name||'未确认实现'}} · {{bridge?.account||'未连接账号'}}</small></div></div><p v-for="warning in warnings" :key="warning" class="notice">{{warning}}</p><p v-if="ui.error.value" class="notice" role="alert">{{ui.error.value}}</p></section>
 <QzoneSocialSettings :request="request" :notify="notify"/>
 <div class="qq-scenarios" role="tablist" aria-label="群工作场景"><button v-for="[id,label,hint] in scenes" :key="id" role="tab" :aria-selected="scene===id" :class="{active:scene===id}" @click="scene=id"><strong>{{label}}</strong><span>{{hint}}</span></button></div>
 <section v-if="scene==='handoff'" class="panel"><div class="panel-head"><div><h3>离开一会儿，回来接上事情</h3><p>整理近期讨论、明确决定和待确认事项，每条可回看原文依据。</p></div></div><div class="panel-body"><div class="row"><select v-model="briefMode" class="input qq-purpose" aria-label="简报用途"><option value="handoff">交接：先看决定与待跟进</option><option value="catchup">补课：先了解讨论来龙去脉</option></select><button class="button primary" :disabled="!group||briefBusy" @click="makeBrief">{{briefBusy?'正在核对近期资料…':'生成交接草稿'}}</button><button v-if="brief?.status==='draft'" class="button" @click="copyBrief">复制草稿</button></div><p class="small muted">按需读取最近最多50条聊天（仅24小时内）、最多8条公告和8条已有待办，不代表全天完整记录。不会发到群里，也不会自动创建任务。</p><p v-if="briefError" class="notice" role="alert">{{briefError}}</p><template v-if="brief"><div class="qq-result-meta"><span class="badge">{{brief.status==='draft'?'待核对草稿':brief.status==='no_data'?'没有足够资料':'仅原文依据，未生成结论'}}</span><small class="mono">{{stamp(brief.created)}}{{brief.cached?' · 60秒内复用本次结果':''}} · {{brief.sources.length}} 条可核对依据</small></div><p v-for="warning in brief.warnings" :key="warning" class="notice">{{warning}}</p><div v-if="brief.status==='draft'" class="qq-brief-grid"><section v-for="(title,key) in sectionNames" :key="key" class="qq-brief-section"><h4>{{title}}</h4><p v-if="!brief.sections[key]?.length" class="small muted">本次读取范围内没有足够依据。</p><article v-for="(item,index) in brief.sections[key]||[]" :key="index" class="qq-brief-item"><p>{{item.text}}</p><details><summary>核对 {{item.source_ids.length}} 条依据</summary><blockquote v-for="source in evidence(item.source_ids)" :key="source.id" class="quote"><small>{{sourceNames[source.kind]}} · {{source.name}} · {{stamp(source.time)}}</small><p class="qq-prewrap">{{source.text}}{{source.truncated?'（摘录已截取）':''}}</p></blockquote></details></article></section></div><details v-if="brief.sources.length" class="qq-source-list"><summary>查看本次实际使用的全部依据</summary><blockquote v-for="source in brief.sources" :key="source.id" class="quote"><small>{{sourceNames[source.kind]}} · {{source.name}} · {{stamp(source.time)}}</small><p class="qq-prewrap">{{source.text}}{{source.truncated?'（摘录已截取）':''}}</p></blockquote></details><p v-if="brief.status==='no_data'" class="notice">没有读到足够的可用文字；不据此推断群里没有活动。</p></template></div></section>
 <section v-if="scene==='materials'" class="panel"><div class="panel-head"><div><h3>让Yuna看懂这个群的资料</h3><p>先核对文件原文与版本，再在群里按实际问题请求她参考。</p></div><button class="button small" :disabled="filesBusy||!group" @click="loadFiles()">{{filesBusy?'读取目录中…':'更新目录'}}</button></div><div class="panel-body"><p v-if="autonomy&&effective.files===false" class="notice">此群文件读取已关闭。<button class="button small" @click="scene='ability'">去检查能力开关</button></p><div class="row"><button v-if="folder" class="button small ghost" @click="loadFiles('','')">← 返回根目录</button><span class="small muted">{{folderName||'群文件根目录'}} · 仅支持一层目录</span><input v-model="fileQuery" class="input search" type="search" placeholder="搜索群规、活动材料、作业要求…" aria-label="搜索群资料"></div><p class="small muted">支持2MB以内的文本、DOCX与文字PDF，最多摘录6000字；读取后保留群、文件、时间与版本。不会把文件内容当成执行指令或直接改写人格。</p><p v-if="fileError" class="notice" role="alert">{{fileError}}</p></div><div class="table-wrap"><table><thead><tr><th>群资料</th><th>大小 / 可用性</th><th>下一步</th></tr></thead><tbody><tr v-for="file in pageRows(filteredFiles,filePage)" :key="file.id"><td>{{file.folder?'▤ ':''}}{{file.name}}</td><td>{{file.folder?'目录':(file.size/1024).toFixed(1)+' KB'}}<small v-if="file.reason" class="qq-block muted">{{file.reason}}</small></td><td><button v-if="file.folder" class="button small" @click="loadFiles(file.id,file.name)">打开目录</button><button v-else class="button small" :disabled="!file.readable||effective.files===false" @click="readFile(file)">核对并读取原文</button></td></tr></tbody></table></div><div v-if="!filesBusy&&!filteredFiles.length" class="empty">本次目录内没有匹配资料，可更新目录或换一个关键词。</div><Pager :total="filteredFiles.length" v-model:page="filePage"/><div class="panel-body"><p v-if="docsTruncated" class="notice">目录超过150项，本次已截取；请按子目录查找。</p><h4>本群最近读取过的资料</h4><p v-if="!notes.length" class="small muted">还没有读取记录。打开上方文件后，可在群里直接问她文件里的具体问题。</p><div v-for="note in notes" :key="note.file_id" class="qq-note"><div><strong>{{note.name}}</strong><small class="mono">{{stamp(note.time)}} · 内容指纹 {{note.hash.slice(0,12)}} · {{Date.now()/1000-note.time>3600?'已过缓存期，需重新核对':'使用前仍会核对版本'}}</small></div><button class="button small ghost" @click="copy(`请参考群文件《${note.name}》，说明这次需要准备什么；注明依据，不确定的部分先告诉我。`)">复制提问示例</button></div></div></section>
 <section v-if="scene==='ability'" class="panel"><div class="panel-head"><div><h3>这个群为什么没生效？</h3><p>检查可验证的前置条件；不把未接话直接归因于某个开关。</p></div></div><div class="panel-body"><div class="qq-checks"><article><strong>QQ 连接</strong><p>{{freshness.bridge&&bridge?.status?.good?'接口连接正常':'未确认正常，先更新状态或核对登录'}}</p></article><article><strong>聊天插件</strong><p>{{freshness.plugins&&chatPlugin?chatPlugin.enabled?'事件响应已启用':'事件响应已停用':'未读取到插件状态'}}</p><button class="button small ghost" @click="navigate('system')">查看插件设置</button></article><article><strong>本群聊天范围</strong><p>{{!freshness.whitelist?'未读取到白名单':whiteEntry?.enabled===true?'已启用聊天':whiteEntry?'本群聊天已停用':'本群未加入聊天白名单'}}</p><button class="button small ghost" @click="navigate('whitelist')">管理聊天白名单</button></article></div><p class="small muted">以上条件正常，也不代表每句话都应该回应：是否在对Yuna说话、是否需要补查，仍由实际上下文判断。下面只管理工具能力，不改变聊天指向规则。</p><form class="qq-scope-form" @submit.prevent="saveRule"><label v-for="[key,label,hint] in [['history','补齐上下文','被问到前面的内容时，在当前会话按需补查'],['files','读取群文件','被请求解释文件时，按需读取并注明来源'],['reactions','表情回应','轻松的确认或玩笑可用表情回应，避免每次长回复']]" :key="key"><div><strong>{{label}}</strong><small>{{hint}}</small></div><select v-model="groupRule[key]" class="input" :aria-label="'本群'+label" :disabled="!autonomy||!freshness.policy||ui.pending.has('scope:'+group)" @change="scopeDirty=true;changedCapabilities.add(key)"><option value="">跟随全局（{{autonomy?.policy?.[key]?'开启':'关闭'}}）</option><option value="true">此群开启</option><option value="false">此群关闭</option></select></label><button class="button primary small" :disabled="!scopeDirty||!autonomy||!freshness.policy||ui.pending.has('scope:'+group)" type="submit">保存此群能力</button></form><p v-if="autonomy" class="small muted">全局表情上限每群每天 {{autonomy.policy.reaction_daily}} 次，间隔 {{autonomy.policy.reaction_cooldown}} 秒，静默 {{autonomy.policy.quiet_start}}:00—{{autonomy.policy.quiet_end}}:00。其他群和全局设置不会随本群保存而改变。</p><p v-if="autonomy?.warning" class="notice">{{autonomy.warning}}</p><h4>此群最近的工具执行结果</h4><p class="small muted">从最近80条全局工具活动中筛选本群；没有记录不代表没收过消息。</p><div v-if="!activity.length" class="empty">暂无本群工具调用记录</div><article v-for="event in pageRows(activity,activityPage)" :key="event.id" class="qq-event"><div><strong>{{event.summary}}</strong><small class="mono">{{stamp(event.time)}} · {{event.action}} · {{event.status==='succeeded'?'成功':event.status==='failed'?'失败':event.status==='unknown'?'结果待核对':event.status}}</small></div><button class="button small" @click="showDetail('执行结果与依据',`qq/activity/${encodeURIComponent(event.id)}`)">查看详情</button></article><Pager :total="activity.length" v-model:page="activityPage"/></div></section>
 <details class="panel qq-advanced"><summary>高级查询：公告、容量、荣誉与原始群资源</summary><div class="panel-body"><div class="row"><select v-model="rawKind" class="input qq-purpose" aria-label="高级资源类型"><option v-for="[id,label] in [['notices','群公告'],['storage','文件容量'],['honor','群荣誉'],['todos','已有群待办'],['essence','群精华'],['history','最近聊天']]" :key="id" :value="id">{{label}}</option></select><button class="button small" :disabled="!group||rawBusy" @click="rawRead">查询</button></div><div v-if="rawResult"><p class="small muted">本次 {{rawResult.returned}} 项，仅代表接口实际返回范围。</p><div v-for="(row,index) in rawResult.items" :key="index" class="quote"><strong>{{row.name||row.speaker||'—'}}</strong><p class="qq-prewrap">{{row.text||'没有可读文字'}}</p></div></div></div></details>
 </template>
 <dialog ref="dialog" class="migration-dialog" aria-labelledby="qq-detail-title" @cancel.prevent="close"><header class="drawer-head"><h3 id="qq-detail-title">{{detailTitle}}</h3><button class="close" aria-label="关闭群工作详情" @click="close">×</button></header><div class="drawer-body"><p v-if="detailBusy">正在读取与核对…</p><p v-if="detailError" class="notice" role="alert">{{detailError}}</p><textarea v-if="copyText" ref="copyField" readonly class="input qq-copy" :value="copyText" aria-label="可复制草稿"></textarea><template v-if="detail?.excerpt"><p class="small muted">{{detail.name}} · {{stamp(detail.time)}} · {{detail.cached?'复用已核对版本':'本次读取'}} · 最多6000字摘录</p><p class="quote qq-prewrap">{{detail.excerpt}}</p></template><pre v-else-if="detail" class="migration-text">{{JSON.stringify(detail,null,2)}}</pre></div></dialog>
</div></template>
